-- Généré avec DrawDB, puis corrigé à la main (nom du client, statut de commande, contraintes)

CREATE TYPE "role" AS ENUM (
	'Administrateur',
	'Collaborateur'
);

-- Statut d'une commande : valeurs sans accent pour simplifier le PHP,
-- l'affichage (« À faire », « En cours »…) est géré côté React
CREATE TYPE "statut_commande" AS ENUM (
	'a_faire',
	'en_cours',
	'terminee',
	'livree'
);

CREATE TABLE IF NOT EXISTS "utilisateur" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY, --clé primaire unique
	"identifiant" VARCHAR(25) NOT NULL UNIQUE, -- UNIQUE : deux comptes ne peuvent pas avoir le même identifiant (connexion)
	"mdp" VARCHAR(100) NOT NULL, -- On laisse une taille de mdp longue pour prévoir le hashage
	"email" VARCHAR(120) NOT NULL UNIQUE, -- UNIQUE : un email = un seul compte
	"nom" VARCHAR(50) NOT NULL,
	"organisation_id" INTEGER NOT NULL,
	"role" VARCHAR(20) NOT NULL CHECK ("role" IN ('administrateur', 'collaborateur')),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "organisation" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY, --clé primaire unique
	"nom" VARCHAR(50) NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "commande" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY, --clé primaire unique
	"nom_client" VARCHAR(100) NOT NULL, -- le client est identifié par son nom, plus seulement par le numéro de commande
	"date_creation" DATE NOT NULL DEFAULT CURRENT_DATE, -- remplie automatiquement à la création
	"statut" VARCHAR(20) NOT NULL DEFAULT 'a_faire' CHECK ("statut" IN ('a_faire', 'en_cours', 'termine', 'livree')), -- une nouvelle commande commence « à faire »
	"utilisateur_id" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "commande_ticket" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY, --clé primaire unique
	"utilisateur_id" INTEGER, -- Utilisateur nullable
	"piece_id" INTEGER NOT NULL,
	"commande_id" INTEGER NOT NULL,
	"etape_id" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "piece" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY, --clé primaire unique
	"nom" VARCHAR(25) NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "etape" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY, --clé primaire unique
	"nom" VARCHAR(25) NOT NULL, -- une étape a forcément un nom
	"ordre" INTEGER NOT NULL UNIQUE, -- sert à trouver l'étape suivante : obligatoire, et jamais deux étapes au même rang
	PRIMARY KEY("id")
);

ALTER TABLE "utilisateur"
ADD FOREIGN KEY ("organisation_id") REFERENCES "organisation" ("id");

ALTER TABLE "commande"
ADD FOREIGN KEY ("utilisateur_id") REFERENCES "utilisateur" ("id");

ALTER TABLE "commande_ticket"
ADD FOREIGN KEY ("commande_id") REFERENCES "commande" ("id");

ALTER TABLE "commande_ticket"
ADD FOREIGN KEY ("piece_id") REFERENCES "piece" ("id");

ALTER TABLE "commande_ticket"
ADD FOREIGN KEY ("etape_id") REFERENCES "etape" ("id");

ALTER TABLE "commande_ticket"
ADD FOREIGN KEY ("utilisateur_id") REFERENCES "utilisateur" ("id");
